import {MONTHS,CATEGORIES,SHEET_ID,SOURCES,csv,parseMain,parsePersonal,sum,escapeHTML as esc,ledgerRows} from './data.mjs';
import {API_URL} from './config.js';
const $=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n),today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let endpoint=localStorage.getItem('casa.endpoint')||API_URL,token='',email='',entries=[],parsed=null,personal={},personalIssues={},page=1,view='overview',busy=false,saveBusy=false,pendingRequest=null,person='Maina',loaded=false;
const current=today().slice(0,7);let selected=current;
const session=()=>{try{return JSON.parse(sessionStorage.getItem('casa.session')||'null')}catch{return null}};
const validEndpoint=url=>/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(url);
function notify(message){$('toast').textContent=message;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4500)}
function banner(message){$('errorBanner').textContent=message;$('errorBanner').hidden=!message}
async function api(action,payload={}){if(!validEndpoint(endpoint))throw Error('Configure a conexão de gravação em Configurações.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,token,...payload}),signal:controller.signal,redirect:'follow'});if(!response.ok)throw Error('O serviço não respondeu. Verifique a conexão.');const result=await response.json();if(!result.ok){if(result.code==='AUTH'){token='';sessionStorage.removeItem('casa.session');}throw Error(result.error||'Não foi possível concluir a solicitação.');}return result;}finally{clearTimeout(timer)}}
async function publicRead(gid){const r=await fetch(`https://docs.google.com/spreadsheets/d/${SHEET_ID}/export?format=csv&gid=${gid}`,{cache:'no-store',signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('Não foi possível ler a planilha. Tente atualizar novamente.');return csv(await r.text());}
function periodOptions(){const years=[...new Set([...(parsed?.years||[]),...entries.map(e=>Number(e.period.slice(0,4))),Number(selected.slice(0,4)),Number(current.slice(0,4))])].sort((a,b)=>b-a);$('year').innerHTML=years.map(y=>`<option>${y}</option>`).join('');$('year').value=selected.slice(0,4);$('month').value=String(Number(selected.slice(5)));}
function setPeriod(p){selected=p;page=1;periodOptions();render();}
function baseRows(range='month'){return entries.filter(e=>(!$('owner').value||e.owner===$('owner').value)&&(range==='all'||(range==='year'?e.period.startsWith(selected.slice(0,4)):e.period===selected)));}
function filtered(){const q=$('search').value.toLocaleLowerCase('pt-BR');return baseRows($('rangeFilter').value).filter(e=>(!$('typeFilter').value||e.type===$('typeFilter').value)&&(!$('categoryFilter').value||e.category===$('categoryFilter').value)&&(!$('statusFilter').value||e.status===$('statusFilter').value)&&(!q||`${e.description} ${e.category} ${e.note}`.toLocaleLowerCase('pt-BR').includes(q))).sort((a,b)=>`${b.period}${b.date}`.localeCompare(`${a.period}${a.date}`));}
function sourceLink(e){return `https://docs.google.com/spreadsheets/d/${SHEET_ID}/edit#gid=${e.gid}&range=${e.cell}`;}
function rowHTML(e){return `<tr><td>${esc(e.date?e.date.split('-').reverse().join('/'):'Mensal')}<small>${esc(e.period.slice(5)+'/'+e.period.slice(0,4))}</small></td><td><strong>${esc(e.description)}</strong>${e.note?`<small>${esc(e.note)}</small>`:''}</td><td>${esc(e.category)}</td><td>${esc(e.owner)}</td><td><span class="tag ${e.status==='Pendente'?'pending':''}">${esc(e.status)}</span></td><td class="money ${e.type==='Receita'?'income':'expense'}">${e.type==='Receita'?'+':'−'} ${fmt(e.amount)}</td><td><a class="source-link" href="${sourceLink(e)}" target="_blank" rel="noopener">${esc(e.source)} ↗</a></td></tr>`;}
function renderHistory(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/30));page=Math.min(page,pages);$('historyRows').innerHTML=rows.slice((page-1)*30,page*30).map(rowHTML).join('')||'<tr><td colspan="7" class="empty">Nenhum lançamento para estes filtros.</td></tr>';$('historyCount').textContent=`${rows.length} registros · Receitas ${fmt(sum(rows,'Receita'))} · Despesas ${fmt(sum(rows,'Despesa'))}`;$('pageInfo').textContent=`Página ${page} de ${pages}`;$('pagePrev').disabled=page===1;$('pageNext').disabled=page===pages;}
function render(){const rows=baseRows(),income=sum(rows,'Receita'),expense=sum(rows,'Despesa');for(const [id,value] of Object.entries({balance:income-expense,income,expense,pending:sum(rows.filter(e=>e.status==='Pendente'),'Despesa')}))$(id).textContent=loaded?fmt(value):'—';$('incomeCount').textContent=`${rows.filter(e=>e.type==='Receita').length} entradas no mês`;$('incomeHint').textContent=income?'':'Receitas não informadas neste período.';let prev=new Date(Number(selected.slice(0,4)),Number(selected.slice(5))-2,1);const pp=`${prev.getFullYear()}-${String(prev.getMonth()+1).padStart(2,'0')}`,pr=entries.filter(e=>e.period===pp&&(!$('owner').value||e.owner===$('owner').value));const previous=sum(pr,'Despesa');$('expenseChange').textContent=previous?`${((expense/previous-1)*100).toFixed(1).replace('.',',')}% em relação ao mês anterior`:'Sem base de comparação no mês anterior';
const yr=baseRows('year'),monthly=MONTHS.map((_,i)=>{const r=yr.filter(e=>e.period===`${selected.slice(0,4)}-${String(i+1).padStart(2,'0')}`);return [sum(r,'Receita'),sum(r,'Despesa')]}),max=Math.max(1,...monthly.flat());$('yearChart').innerHTML=MONTHS.map((m,i)=>`<button class="month-bar ${i+1===Number(selected.slice(5))?'selected':''}" data-month="${i+1}" title="${m}: receitas ${fmt(monthly[i][0])}; despesas ${fmt(monthly[i][1])}" aria-label="${m}: receitas ${fmt(monthly[i][0])}; despesas ${fmt(monthly[i][1])}"><div class="bar-pair"><i style="height:${Math.max(0,monthly[i][0])/max*100}%"></i><i style="height:${Math.max(0,monthly[i][1])/max*100}%"></i></div><span>${m.slice(0,3)}</span></button>`).join('');
const cats={};rows.filter(e=>e.type==='Despesa').forEach(e=>cats[e.category]=(cats[e.category]||0)+e.amount);$('categoryChart').innerHTML=Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="category-row"><div><span>${esc(c)}</span><strong>${fmt(v)} · ${expense?(v/expense*100).toFixed(0):0}%</strong></div><div class="track"><i style="width:${expense?Math.max(0,v/expense*100):0}%"></i></div></div>`).join('')||'<p class="empty">Sem despesas neste mês.</p>';
$('overviewCount').textContent=`${rows.length} registros · ${MONTHS[Number(selected.slice(5))-1]} ${selected.slice(0,4)}`;$('recentRows').innerHTML=rows.slice().sort((a,b)=>b.amount-a.amount).slice(0,7).map(e=>`<div class="movement"><span class="badge">${e.type==='Receita'?'↙':'↗'}</span><div><strong>${esc(e.description)}</strong><p>${esc(e.category)} · ${esc(e.owner)} · ${esc(e.status)}</p></div><strong class="${e.type==='Receita'?'income':'expense'}">${fmt(e.amount)}</strong></div>`).join('')||'<p class="empty">Nenhum movimento no período.</p>';
const budget=Number(localStorage.getItem(`casa.budget.${$('owner').value}.${selected}`)||0);$('budgetView').innerHTML=budget?`<strong class="budget-amount">${fmt(budget-expense)}</strong><p>${budget>=expense?'disponíveis':'acima do limite'} · limite ${fmt(budget)}</p><div class="track"><i style="width:${Math.min(100,Math.max(0,expense/budget*100))}%"></i></div><p class="footnote">${(expense/budget*100).toFixed(0)}% utilizado no filtro atual</p>`:'<p>Defina um limite para acompanhar quanto ainda pode gastar neste mês.</p>';$('budget').value=budget||'';$('budgetPeriod').textContent=`${$('owner').value} · ${MONTHS[Number(selected.slice(5))-1]} de ${selected.slice(0,4)}`;const issues=parsed?.issues.filter(i=>i.period===selected)||[];$('quality').textContent=issues.length?`${issues.length} valores não numéricos ignorados (${issues.map(i=>i.cell).join(', ')}). Confira a planilha.`:'Nenhum valor não numérico encontrado neste mês.';if($('owner').value!=='Casa')$('quality').textContent=(personalIssues[$('owner').value]||[]).join(' ');renderHistory();}
function navigate(next){view=next;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==next);document.querySelectorAll('nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===next));$('pageTitle').textContent={overview:'Visão do mês',history:'Histórico',personal:'Abas pessoais',settings:'Configurações'}[next];$('periodBar').hidden=next==='personal';if(next==='personal')loadPersonal();if(next==='settings')renderSettings();}
function renderSettings(){$('endpoint').value=endpoint;$('backendStatus').textContent=endpoint?'Serviço configurado. Os lançamentos são confirmados após gravação e leitura de volta.':'Modo de consulta. Conecte o serviço para salvar lançamentos na planilha.';$('connectionBadge').textContent=endpoint?'Leitura e gravação':'Consulta da planilha';}
async function refresh(){if(busy)return;busy=true;$('refresh').disabled=true;$('syncStatus').textContent='Atualizando os dados da planilha…';banner('');try{let main,ledger=[];if(endpoint){const data=await api('read');main=data.main;ledger=ledgerRows(data.ledger,data.ledgerGid);personal=data.personal||{};}else {const data=await Promise.all([publicRead(SOURCES.Casa.gid),publicRead(SOURCES.Maina.gid)]);main=data[0];personal.Maina=data[1];}const next=parseMain(main);parsed=next;const maina=parsePersonal(personal.Maina||[],'Maina');personalIssues={Maina:maina.issues,Diogo:parsePersonal([],'Diogo').issues};entries=[...next.entries,...maina.entries,...ledger];loaded=true;periodOptions();const old=$('categoryFilter').value;$('categoryFilter').innerHTML='<option value="">Todas</option>'+[...new Set(entries.map(e=>e.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('');$('categoryFilter').value=old;$('syncStatus').textContent=`Atualizado às ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})} · ${entries.length} registros em ${parsed.years.length} anos`;$('footerStatus').textContent=endpoint?'Dados lidos diretamente da planilha':'Consulta ativa · gravação aguardando conexão';render();}catch(e){$('syncStatus').textContent=loaded?'Atualização falhou · dados anteriores mantidos':'Não foi possível carregar a planilha';banner(e.message);}finally{busy=false;$('refresh').disabled=false;}}
async function loadPersonal(){const target=person;$('personalStatus').textContent='Carregando…';$('personalTable').innerHTML='';try{const rows=personal[target]||await publicRead(SOURCES[target].gid);personal[target]=rows;if(person!==target)return;const width=Math.min(27,Math.max(1,...rows.map(r=>r.length)));$('personalTable').innerHTML=`<thead><tr><th>Linha</th>${Array.from({length:width},(_,i)=>`<th>${i<26?String.fromCharCode(65+i):'AA'}</th>`).join('')}</tr></thead><tbody>`+rows.map((r,i)=>r.some(v=>String(v??'').trim())?`<tr><th>${i+1}</th>${Array.from({length:width},(_,j)=>`<td>${esc(r[j])}</td>`).join('')}</tr>`:'').join('')+'</tbody>';$('personalStatus').textContent=`${SOURCES[target].name} · exibida separadamente para evitar duplicidades`;}catch(e){$('personalStatus').textContent=e.message;}}
function logout(){sessionStorage.removeItem('casa.session');token='';entries=[];loaded=false;personal={};$('app').hidden=true;$('login').hidden=false;$('loginForm').reset();}
async function enter(){ $('login').hidden=true;$('app').hidden=false;renderSettings();await refresh();}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('loginError').textContent='';const f=new FormData(e.target);email=String(f.get('email')).trim().toLowerCase();try{if(endpoint){const result=await api('login',{email,password:f.get('password')});token=result.token;}else{const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(f.get('password'))))].map(v=>v.toString(16).padStart(2,'0')).join('');if(!['camanodiogo@gmail.com','maina.rymsza@gmail.com'].includes(email)||hash!=='8e49d97aacc8394661e90d889e1f85b538b3ce46306be25c214d9ae84aabc530')throw Error('E-mail ou senha inválidos.');}sessionStorage.setItem('casa.session',JSON.stringify({email,token,endpoint,expires:Date.now()+3600000}));e.target.reset();await enter();}catch(err){$('loginError').textContent=err.message;}finally{button.disabled=false;}});
function openEntry(){if(saveBusy)return;pendingRequest=null;$('entryForm').reset();$('entryForm').elements.owner.value=$('owner').value||'Casa';$('entryForm').elements.date.value=today();$('entryForm').elements.period.value=selected;$('entryMessage').textContent=endpoint?'O registro será salvo na aba Lançamentos Painel.':'A gravação ainda não está conectada. Configure o serviço em Configurações.';$('saveEntry').disabled=!endpoint||!token;$('entryDialog').showModal();}
function closeEntry(){if(saveBusy){$('entryMessage').textContent='Aguarde a confirmação da gravação.';return;}$('entryDialog').close();}
$('entryForm').addEventListener('submit',async e=>{e.preventDefault();if(saveBusy)return;if(!endpoint||!token){$('entryMessage').textContent='Conecte o serviço e entre novamente para gravar.';return;}const payload=Object.fromEntries(new FormData(e.target));payload.amount=Number(payload.amount);const signature=JSON.stringify(payload);if(!pendingRequest||pendingRequest.signature!==signature)pendingRequest={signature,id:crypto.randomUUID()};saveBusy=true;$('saveEntry').disabled=true;$('entryMessage').textContent='Salvando e conferindo na planilha…';try{const result=await api('append',{entry:{...payload,id:pendingRequest.id}});if(result.id!==pendingRequest.id)throw Error('Não foi possível confirmar o identificador salvo.');$('entryDialog').close();pendingRequest=null;notify('Lançamento confirmado na planilha.');selected=payload.period;await refresh();}catch(err){$('entryMessage').textContent=`${err.message} O formulário foi mantido. Se tentar novamente sem editar, usaremos o mesmo identificador para evitar duplicação.`;}finally{saveBusy=false;$('saveEntry').disabled=false;}});
function saveEndpoint(url){url=url.trim();if(!validEndpoint(url))throw Error('Use a URL https://script.google.com/macros/s/…/exec.');localStorage.setItem('casa.endpoint',url);endpoint=url;logout();notify('Conexão salva. Entre novamente.');}
$('connectionForm').addEventListener('submit',e=>{e.preventDefault();try{saveEndpoint($('endpoint').value)}catch(err){notify(err.message)}});$('quickConnect').addEventListener('submit',e=>{e.preventDefault();try{saveEndpoint(new FormData(e.target).get('url'));$('connectDialog').close()}catch(err){$('connectError').textContent=err.message}});
$('budgetForm').addEventListener('submit',e=>{e.preventDefault();localStorage.setItem(`casa.budget.${$('owner').value}.${selected}`,$('budget').value||'0');render();notify('Limite do mês salvo.');});
$('export').addEventListener('click',()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const lines=[['Data','Competência','Tipo','Descrição','Categoria','Responsável','Valor','Situação','Origem'],...filtered().map(e=>[e.date,e.period,e.type,e.description,e.category,e.owner,e.amount.toFixed(2).replace('.',','),e.status,e.source])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`financas-${selected}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.querySelectorAll('[data-person]').forEach(b=>b.addEventListener('click',()=>{person=b.dataset.person;document.querySelectorAll('[data-person]').forEach(x=>x.classList.toggle('active',x===b));loadPersonal()}));
$('yearChart').addEventListener('click',e=>{const b=e.target.closest('[data-month]');if(b)setPeriod(`${selected.slice(0,4)}-${b.dataset.month.padStart(2,'0')}`)});
for(const id of ['search','typeFilter','categoryFilter','statusFilter','rangeFilter'])$(id).addEventListener('input',()=>{page=1;renderHistory()});$('owner').addEventListener('change',()=>{page=1;render()});document.querySelectorAll('[data-scope]').forEach(b=>b.addEventListener('click',()=>{$('owner').value=b.dataset.scope;document.querySelectorAll('[data-scope]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});page=1;render()}));for(const id of ['year','month'])$(id).addEventListener('change',()=>setPeriod(`${$('year').value}-${$('month').value.padStart(2,'0')}`));
for(const [id,step] of [['prevMonth',-1],['nextMonth',1]])$(id).addEventListener('click',()=>{const d=new Date(Number(selected.slice(0,4)),Number(selected.slice(5))-1+step,1);setPeriod(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)});
$('pagePrev').onclick=()=>{page--;renderHistory()};$('pageNext').onclick=()=>{page++;renderHistory()};$('newEntry').onclick=openEntry;$('closeEntry').onclick=closeEntry;$('cancelEntry').onclick=closeEntry;$('entryDialog').addEventListener('cancel',e=>{if(saveBusy)e.preventDefault()});$('entryDialog').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();if(e.target===e.currentTarget&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeEntry()});$('refresh').onclick=refresh;$('logout').onclick=logout;$('loginConnect').onclick=()=>$('connectDialog').showModal();$('cancelConnect').onclick=()=>$('connectDialog').close();$('sheetLink').href=`https://docs.google.com/spreadsheets/d/${SHEET_ID}/edit`;
$('month').innerHTML=MONTHS.map((m,i)=>`<option value="${i+1}">${m}</option>`).join('');$('entryCategory').innerHTML=CATEGORIES.map(c=>`<option>${c}</option>`).join('');periodOptions();const saved=session();if(saved&&saved.expires>Date.now()&&saved.endpoint===endpoint){email=saved.email;token=saved.token;enter();}
